                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==bgv and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                touch=any(y==0 or y==H-1 or x==0 or x==W-1 for y,x in comp)
                marks=sum(1 for (y,x) in comp if any(0<=y+dy<H and 0<=x+dx<W and g[y+dy][x+dx]!=bgv for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]))
                if not touch and marks>=minm:
                    for (y,x) in comp: res[y][x]=fill
    return res
